// Update changes a subscription's plan or quantity. A change that raises the subscription's value (its plan's unit amount
// times its quantity) is an upgrade: it applies at once and its unused and remaining time are billed at once. A change that
// lowers it is a downgrade: it becomes pending and applies at the next renewal. A change that keeps the value equal, and any
// change of a trialing subscription, applies at once and bills nothing.
func (s *Service) Update(ctx context.Context, orgID, id string, in UpdateInput) (store.Subscription, error) {
	if in.PlanID != nil {
		p, ok := s.Store.Plan(orgID, *in.PlanID)
		if !ok {
			return store.Subscription{}, store.ErrNotFound
		}
		if !p.Active {
			return store.Subscription{}, ErrPlanInactive
		}
	}
	cur, ok := s.Store.Subscription(orgID, id)
	if !ok {
		return store.Subscription{}, store.ErrNotFound
	}
	if cur.Status == store.Canceled {
		return store.Subscription{}, ErrCanceled
	}
	oldPlan, ok := s.Store.Plan(orgID, cur.PlanID)
	if !ok {
		return store.Subscription{}, store.ErrNotFound
	}
	newPlan, quantity := oldPlan, cur.Quantity
	if in.PlanID != nil {
		newPlan, _ = s.Store.Plan(orgID, *in.PlanID)
	}
	if in.Quantity != nil {
		quantity = *in.Quantity
	}
	changed := newPlan.ID != oldPlan.ID || quantity != cur.Quantity
	if changed && (oldPlan.UsageType == store.Metered || newPlan.UsageType == store.Metered ||
		oldPlan.Currency != newPlan.Currency || oldPlan.Interval != newPlan.Interval) {
		return store.Subscription{}, ErrIncompatiblePlan
	}
	oldValue := oldPlan.UnitAmount * int64(cur.Quantity)
	newValue := newPlan.UnitAmount * int64(quantity)
	trialing := cur.Status == store.Trialing
	downgrade := !trialing && newValue < oldValue
	upgrade := !trialing && newValue > oldValue

	sub, err := s.Store.UpdateSubscription(orgID, id, func(sub *store.Subscription) error {
		if sub.Status == store.Canceled {
			return ErrCanceled
		}
		if downgrade {
			planID := newPlan.ID
			sub.PendingPlanID, sub.PendingQuantity = &planID, &quantity
			return nil
		}
		if in.PlanID != nil {
			sub.PlanID = *in.PlanID
		}
		if in.Quantity != nil {
			sub.Quantity = *in.Quantity
		}
		sub.PendingPlanID, sub.PendingQuantity = nil, nil
		return nil
	})
	if err != nil {
		return store.Subscription{}, err
	}
	s.publish(ctx, orgID, "subscription.updated", sub)
	if !upgrade {
		return sub, nil
	}
	paid, err := s.prorate(ctx, sub, oldPlan, newPlan, oldValue, newValue)
	if err != nil {
		return sub, err
	}
	if !paid {
		return s.setStatus(ctx, sub, store.PastDue)
	}
	return sub, nil
}

// prorate bills an upgrade for the time left in the current period: the unused part of the old value is credited and the
// remaining part of the new value is charged. The period does not change.
func (s *Service) prorate(ctx context.Context, sub store.Subscription, oldPlan, newPlan store.Plan, oldValue, newValue int64) (bool, error) {
	now := s.Clock.Now()
	remaining := int64(sub.CurrentPeriodEnd.Sub(now) / time.Second)
	length := int64(sub.CurrentPeriodEnd.Sub(sub.CurrentPeriodStart) / time.Second)
	lines := []store.Line{
		{Description: "Unused time on " + oldPlan.Name, Quantity: 1, UnitAmount: -money.Prorate(oldValue, remaining, length)},
		{Description: "Remaining time on " + newPlan.Name, Quantity: 1, UnitAmount: money.Prorate(newValue, remaining, length)},
	}
	return s.bill(ctx, sub, newPlan.Currency, lines, now, sub.CurrentPeriodEnd)
}

