// plan makes a monthly licensed plan of the Acme organization in USD, priced in minor units.
func plan(t *testing.T, e *apitest.Env, name string, unit int64) store.Plan {
	t.Helper()
	p, err := e.Store.CreatePlan(store.Plan{OrgID: e.Acme.ID, Name: name, Currency: money.USD, UnitAmount: unit, Interval: store.Monthly}, e.Clock.Now())
	if err != nil {
		t.Fatal(err)
	}
	return p
}

// subscribe starts a subscription to p for a new customer whose default payment method is pm (empty for none).
func subscribe(t *testing.T, e *apitest.Env, p store.Plan, pm string, qty, discount int) store.Subscription {
	t.Helper()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	if pm != "" {
		_, _ = e.Store.UpdateCustomer(e.Acme.ID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = pm; return nil })
	}
	sub, err := e.Subs.Create(context.Background(), e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: qty, DiscountPercent: discount})
	if err != nil {
		t.Fatal(err)
	}
	return sub
}

func invoicesOf(e *apitest.Env, sub store.Subscription) []store.Invoice {
	return e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
}

func TestUpgradeBillsTheTimeLeftInThePeriod(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	team, business := plan(t, e, "Team", 2000), plan(t, e, "Business", 5000)
	sub := subscribe(t, e, team, "pm_card_visa", 1, 10)
	// 10 of the period's 31 days have passed: 21 days (1814400 s) of 2678400 s remain.
	e.Clock.Set(sub.CurrentPeriodStart.AddDate(0, 0, 10))
	id := business.ID
	got, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &id})
	if err != nil {
		t.Fatal(err)
	}
	if got.PlanID != business.ID || got.Status != store.Active || !got.CurrentPeriodStart.Equal(sub.CurrentPeriodStart) || !got.CurrentPeriodEnd.Equal(sub.CurrentPeriodEnd) {
		t.Fatalf("subscription = %+v", got)
	}
	invs := invoicesOf(e, sub)
	if len(invs) != 2 {
		t.Fatalf("invoices = %+v", invs)
	}
	up := invs[1]
	// Unused: -round(2000 * 21/31) = -1355. Remaining: round(5000 * 21/31) = 3387. The 10% discount is 203 of 2032.
	want := []store.Line{{Description: "Unused time on Team", Quantity: 1, UnitAmount: -1355}, {Description: "Remaining time on Business", Quantity: 1, UnitAmount: 3387}}
	if len(up.Lines) != 2 || up.Lines[0] != want[0] || up.Lines[1] != want[1] || up.DiscountPercent != 10 || up.Status != store.InvoicePaid {
		t.Fatalf("upgrade invoice = %+v", up)
	}
	if cs := e.Gateway.Charges(); len(cs) != 2 || cs[1].Amount != 1829 {
		t.Fatalf("charges = %+v", cs)
	}
}

func TestDeclinedUpgradeAppliesAndIsPastDue(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	team, business := plan(t, e, "Team", 2000), plan(t, e, "Business", 5000)
	sub := subscribe(t, e, team, "pm_card_visa", 1, 0)
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, sub.CustomerID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_card_declined"; return nil })
	id := business.ID
	got, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &id})
	if err != nil {
		t.Fatal(err)
	}
	if got.PlanID != business.ID || got.Status != store.PastDue {
		t.Fatalf("subscription = %+v", got)
	}
	if invs := invoicesOf(e, sub); len(invs) != 2 || invs[1].Status != store.InvoiceOpen || len(invs[1].Lines) != 2 {
		t.Fatalf("invoices = %+v", invs)
	}
}

func TestUpgradeWithoutPaymentMethodStaysOpen(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	team, business := plan(t, e, "Team", 2000), plan(t, e, "Business", 5000)
	sub := subscribe(t, e, team, "", 1, 0)
	id := business.ID
	got, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &id})
	if err != nil {
		t.Fatal(err)
	}
	if got.PlanID != business.ID || got.Status != store.Active {
		t.Fatalf("subscription = %+v", got)
	}
	if invs := invoicesOf(e, sub); len(invs) != 2 || invs[1].Status != store.InvoiceOpen {
		t.Fatalf("invoices = %+v", invs)
	}
}

func TestDowngradeIsPendingUntilRenewal(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	team, business := plan(t, e, "Team", 2000), plan(t, e, "Business", 5000)
	sub := subscribe(t, e, business, "pm_card_visa", 2, 0)
	id := team.ID
	got, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &id})
	if err != nil {
		t.Fatal(err)
	}
	if got.PlanID != business.ID || got.Quantity != 2 || got.PendingPlanID == nil || *got.PendingPlanID != team.ID || got.PendingQuantity == nil || *got.PendingQuantity != 2 {
		t.Fatalf("subscription = %+v", got)
	}
	if invs := invoicesOf(e, sub); len(invs) != 1 {
		t.Fatalf("a downgrade was billed: %+v", invs)
	}
	e.Clock.Set(sub.CurrentPeriodEnd)
	if n, err := e.Subs.RenewDue(ctx); err != nil || n != 1 {
		t.Fatalf("RenewDue = %d, %v", n, err)
	}
	got, _ = e.Store.Subscription(e.Acme.ID, sub.ID)
	if got.PlanID != team.ID || got.Quantity != 2 || got.PendingPlanID != nil || got.PendingQuantity != nil || got.Status != store.Active {
		t.Fatalf("after renewal = %+v", got)
	}
	invs := invoicesOf(e, sub)
	if len(invs) != 2 || len(invs[1].Lines) != 1 || invs[1].Lines[0].Quantity != 2 || invs[1].Lines[0].UnitAmount != 2000 {
		t.Fatalf("renewal invoice = %+v", invs)
	}
}

func TestPendingChangeIsClearedByAnUpgradeOrByReturningToCurrent(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	team, business := plan(t, e, "Team", 2000), plan(t, e, "Business", 5000)
	sub := subscribe(t, e, business, "pm_card_visa", 2, 0)
	teamID, businessID := team.ID, business.ID
	if _, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &teamID}); err != nil {
		t.Fatal(err)
	}
	got, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &businessID})
	if err != nil {
		t.Fatal(err)
	}
	if got.PlanID != business.ID || got.PendingPlanID != nil || got.PendingQuantity != nil {
		t.Fatalf("back to current = %+v", got)
	}
	if _, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &teamID}); err != nil {
		t.Fatal(err)
	}
	qty := 3
	got, err = e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{Quantity: &qty})
	if err != nil {
		t.Fatal(err)
	}
	if got.PlanID != business.ID || got.Quantity != 3 || got.PendingPlanID != nil || got.PendingQuantity != nil {
		t.Fatalf("upgrade = %+v", got)
	}
}

func TestEqualValueChangeAppliesAtOnceAndBillsNothing(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	team, starter := plan(t, e, "Team", 2000), plan(t, e, "Starter", 1000)
	sub := subscribe(t, e, team, "pm_card_visa", 1, 0)
	id, qty := starter.ID, 2
	got, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &id, Quantity: &qty})
	if err != nil {
		t.Fatal(err)
	}
	if got.PlanID != starter.ID || got.Quantity != 2 || got.PendingPlanID != nil {
		t.Fatalf("subscription = %+v", got)
	}
	if invs := invoicesOf(e, sub); len(invs) != 1 {
		t.Fatalf("an equal change was billed: %+v", invs)
	}
}

func TestTrialingChangeAppliesAtOnceAndBillsNothing(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	trial, _ := e.Store.CreatePlan(store.Plan{OrgID: e.Acme.ID, Name: "Pro", Currency: money.USD, UnitAmount: 5000, Interval: store.Monthly, TrialDays: 14}, e.Clock.Now())
	business := plan(t, e, "Business", 9000)
	sub := subscribe(t, e, trial, "pm_card_visa", 1, 0)
	if sub.Status != store.Trialing {
		t.Fatalf("subscription = %+v", sub)
	}
	id := business.ID
	got, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &id})
	if err != nil {
		t.Fatal(err)
	}
	if got.PlanID != business.ID || got.Status != store.Trialing || got.PendingPlanID != nil {
		t.Fatalf("upgrade in the trial = %+v", got)
	}
	back := trial.ID
	if got, err = e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &back}); err != nil || got.PlanID != trial.ID || got.PendingPlanID != nil {
		t.Fatalf("downgrade in the trial = %+v, %v", got, err)
	}
	if invs := invoicesOf(e, sub); len(invs) != 0 {
		t.Fatalf("a trial change was billed: %+v", invs)
	}
}

func TestIncompatiblePlansAreRefused(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	team := plan(t, e, "Team", 2000)
	sub := subscribe(t, e, team, "", 1, 0)
	eur, _ := e.Store.CreatePlan(store.Plan{OrgID: e.Acme.ID, Name: "Euro", Currency: money.EUR, UnitAmount: 3000, Interval: store.Monthly}, e.Clock.Now())
	yearly, _ := e.Store.CreatePlan(store.Plan{OrgID: e.Acme.ID, Name: "Yearly", Currency: money.USD, UnitAmount: 30000, Interval: store.Yearly}, e.Clock.Now())
	metered, _ := e.Store.CreatePlan(store.Plan{OrgID: e.Acme.ID, Name: "Calls", Currency: money.USD, UnitAmount: 2, Interval: store.Monthly, UsageType: store.Metered}, e.Clock.Now())
	for _, p := range []store.Plan{eur, yearly, metered} {
		id := p.ID
		if _, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &id}); !errors.Is(err, subscriptions.ErrIncompatiblePlan) {
			t.Fatalf("change to %s: err = %v", p.Name, err)
		}
	}
	meteredSub := subscribe(t, e, metered, "", 1, 0)
	qty := 2
	if _, err := e.Subs.Update(ctx, e.Acme.ID, meteredSub.ID, subscriptions.UpdateInput{Quantity: &qty}); !errors.Is(err, subscriptions.ErrIncompatiblePlan) {
		t.Fatalf("quantity of a metered subscription: err = %v", err)
	}
	if got, _ := e.Store.Subscription(e.Acme.ID, sub.ID); got.PlanID != team.ID || len(invoicesOf(e, sub)) != 0 {
		t.Fatalf("a refused change applied: %+v", got)
	}
}
