		t.Fatalf("back to current = %+v", got)
	}
	if _, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &teamID}); err != nil {
		t.Fatal(err)
	}
	qty := 3
	got, err = e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{Quantity: &qty})
	if err != nil {
		t.Fatal(err)
	}
	if got.PlanID != business.ID || got.Quantity != 3 || got.PendingPlanID != nil || got.PendingQuantity != nil {
		t.Fatalf("upgrade = %+v", got)
	}
}

func TestEqualValueChangeAppliesAtOnceAndBillsNothing(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	team, starter := plan(t, e, "Team", 2000), plan(t, e, "Starter", 1000)
	sub := subscribe(t, e, team, "pm_card_visa", 1, 0)
	id, qty := starter.ID, 2
	got, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &id, Quantity: &qty})
	if err != nil {
		t.Fatal(err)
	}
	if got.PlanID != starter.ID || got.Quantity != 2 || got.PendingPlanID != nil {
		t.Fatalf("subscription = %+v", got)
	}
	if invs := invoicesOf(e, sub); len(invs) != 1 {
		t.Fatalf("an equal change was billed: %+v", invs)
	}
}

func TestTrialingChangeAppliesAtOnceAndBillsNothing(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	trial, _ := e.Store.CreatePlan(store.Plan{OrgID: e.Acme.ID, Name: "Pro", Currency: money.USD, UnitAmount: 5000, Interval: store.Monthly, TrialDays: 14}, e.Clock.Now())
	business := plan(t, e, "Business", 9000)
	sub := subscribe(t, e, trial, "pm_card_visa", 1, 0)
	if sub.Status != store.Trialing {
		t.Fatalf("subscription = %+v", sub)
	}
	id := business.ID
	got, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &id})
	if err != nil {
		t.Fatal(err)
	}
	if got.PlanID != business.ID || got.Status != store.Trialing || got.PendingPlanID != nil {
		t.Fatalf("upgrade in the trial = %+v", got)
	}
	back := trial.ID
	if got, err = e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &back}); err != nil || got.PlanID != trial.ID || got.PendingPlanID != nil {
		t.Fatalf("downgrade in the trial = %+v, %v", got, err)
	}
	if invs := invoicesOf(e, sub); len(invs) != 0 {
		t.Fatalf("a trial change was billed: %+v", invs)
	}
}

func TestIncompatiblePlansAreRefused(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	team := plan(t, e, "Team", 2000)
	sub := subscribe(t, e, team, "", 1, 0)
	eur, _ := e.Store.CreatePlan(store.Plan{OrgID: e.Acme.ID, Name: "Euro", Currency: money.EUR, UnitAmount: 3000, Interval: store.Monthly}, e.Clock.Now())
	yearly, _ := e.Store.CreatePlan(store.Plan{OrgID: e.Acme.ID, Name: "Yearly", Currency: money.USD, UnitAmount: 30000, Interval: store.Yearly}, e.Clock.Now())
	metered, _ := e.Store.CreatePlan(store.Plan{OrgID: e.Acme.ID, Name: "Calls", Currency: money.USD, UnitAmount: 2, Interval: store.Monthly, UsageType: store.Metered}, e.Clock.Now())
	for _, p := range []store.Plan{eur, yearly, metered} {
		id := p.ID
		if _, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &id}); !errors.Is(err, subscriptions.ErrIncompatiblePlan) {
			t.Fatalf("change to %s: err = %v", p.Name, err)
		}
	}
	meteredSub := subscribe(t, e, metered, "", 1, 0)
	qty := 2
	if _, err := e.Subs.Update(ctx, e.Acme.ID, meteredSub.ID, subscriptions.UpdateInput{Quantity: &qty}); !errors.Is(err, subscriptions.ErrIncompatiblePlan) {
		t.Fatalf("quantity of a metered subscription: err = %v", err)
	}
	if got, _ := e.Store.Subscription(e.Acme.ID, sub.ID); got.PlanID != team.ID || len(invoicesOf(e, sub)) != 0 {
		t.Fatalf("a refused change applied: %+v", got)
	}
}

