1	// Package subscriptions runs subscriptions: starting them with their first invoice, changing and canceling them, and
2	// renewing them when a billing period ends.
3	package subscriptions
4	
5	import (
6		"context"
7		"errors"
8		"fmt"
9		"time"
10	
11		"example.com/tally/internal/billing"
12		"example.com/tally/internal/clock"
13		"example.com/tally/internal/money"
14		"example.com/tally/internal/payments"
15		"example.com/tally/internal/store"
16	)
17	
18	// Errors.
19	var (
20		ErrPlanInactive     = errors.New("the plan is not active")
21		ErrCanceled         = errors.New("the subscription is canceled")
22		ErrIncompatiblePlan = errors.New("the plans must have the same currency and interval, and neither may be metered")
23	)
24	
25	// Service runs subscriptions.
26	type Service struct {
27		Store     *store.Store
28		Payments  *payments.Service
29		Clock     clock.Clock
30		Publisher payments.Publisher // nil: no events
31	}
32	
33	// CreateInput is a new subscription.
34	type CreateInput struct {
35		CustomerID      string
36		PlanID          string
37		Quantity        int // 0 means 1
38		DiscountPercent int
39	}
40	
41	// Create starts a subscription now. With a plan that has a trial, the subscription is trialing until the trial ends, and
42	// its first period starts then. Otherwise its first period starts now; for a licensed plan that period is invoiced at once
43	// and charged to the customer's default payment method, if it has one (a declined charge makes the subscription past due).
44	func (s *Service) Create(ctx context.Context, orgID string, in CreateInput) (store.Subscription, error) {
45		plan, ok := s.Store.Plan(orgID, in.PlanID)
46		if !ok {
47			return store.Subscription{}, store.ErrNotFound
48		}
49		if !plan.Active {
50			return store.Subscription{}, ErrPlanInactive
51		}
52		if in.Quantity == 0 {
53			in.Quantity = 1
54		}
55		now := s.Clock.Now()
56		sub := store.Subscription{OrgID: orgID, CustomerID: in.CustomerID, PlanID: plan.ID, Quantity: in.Quantity, DiscountPercent: in.DiscountPercent,
57			StartedAt: now, CurrentPeriodStart: now}
58		if plan.TrialDays > 0 {
59			end := now.AddDate(0, 0, plan.TrialDays)
60			sub.Status, sub.TrialEnd, sub.CurrentPeriodEnd = store.Trialing, &end, end
61		} else {
62			sub.Status, sub.CurrentPeriodEnd = store.Active, billing.AddInterval(now, plan.Interval)
63		}
64		sub, err := s.Store.CreateSubscription(sub, now)
65		if err != nil {
66			return store.Subscription{}, err
67		}
68		s.publish(ctx, orgID, "subscription.created", sub)
69		if sub.Status == store.Active && plan.UsageType == store.Licensed {
70			paid, err := s.invoicePeriod(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
71			if err != nil {
72				return sub, err
73			}
74			if !paid {
75				if sub, err = s.setStatus(ctx, sub, store.PastDue); err != nil {
76					return sub, err
77				}
78			}
79		}
80		return sub, nil
81	}
82	
83	// UpdateInput changes a subscription; nil fields stay as they are.
84	type UpdateInput struct {
85		PlanID   *string
86		Quantity *int
87	}
88	
89	// Update changes a subscription's plan or quantity. A change that raises the subscription's value (its plan's unit amount
90	// times its quantity) is an upgrade: it applies at once and its unused and remaining time are billed at once. A change that
91	// lowers it is a downgrade: it becomes pending and applies at the next renewal. A change that keeps the value equal, and any
92	// change of a trialing subscription, applies at once and bills nothing.
93	func (s *Service) Update(ctx context.Context, orgID, id string, in UpdateInput) (store.Subscription, error) {
94		if in.PlanID != nil {
95			p, ok := s.Store.Plan(orgID, *in.PlanID)
96			if !ok {
97				return store.Subscription{}, store.ErrNotFound
98			}
99			if !p.Active {
100				return store.Subscription{}, ErrPlanInactive
101			}
102		}
103		cur, ok := s.Store.Subscription(orgID, id)
104		if !ok {
105			return store.Subscription{}, store.ErrNotFound
106		}
107		if cur.Status == store.Canceled {
108			return store.Subscription{}, ErrCanceled
109		}
110		oldPlan, ok := s.Store.Plan(orgID, cur.PlanID)
111		if !ok {
112			return store.Subscription{}, store.ErrNotFound
113		}
114		newPlan, quantity := oldPlan, cur.Quantity
115		if in.PlanID != nil {
116			newPlan, _ = s.Store.Plan(orgID, *in.PlanID)
117		}
118		if in.Quantity != nil {
119			quantity = *in.Quantity
120		}
121		if quantity <= 0 {
122			return store.Subscription{}, fmt.Errorf("%w: the quantity must be at least 1", store.ErrInvalid)
123		}
124		changed :=newPlan.ID != oldPlan.ID || quantity != cur.Quantity
125		if changed && (oldPlan.UsageType == store.Metered || newPlan.UsageType == store.Metered ||
126			oldPlan.Currency != newPlan.Currency || oldPlan.Interval != newPlan.Interval) {
127			return store.Subscription{}, ErrIncompatiblePlan
128		}
129		oldValue := oldPlan.UnitAmount * int64(cur.Quantity)
130		newValue := newPlan.UnitAmount * int64(quantity)
131		trialing := cur.Status == store.Trialing
132		downgrade := !trialing && newValue < oldValue
133		upgrade := !trialing && newValue > oldValue
134	
135		sub, err := s.Store.UpdateSubscription(orgID, id, func(sub *store.Subscription) error {
136			if sub.Status == store.Canceled {
137				return ErrCanceled
138			}
139			if downgrade {
140				planID := newPlan.ID
141				sub.PendingPlanID, sub.PendingQuantity = &planID, &quantity
142				return nil
143			}
144			if in.PlanID != nil {
145				sub.PlanID = *in.PlanID
146			}
147			if in.Quantity != nil {
148				sub.Quantity = *in.Quantity
149			}
150			sub.PendingPlanID, sub.PendingQuantity = nil, nil
151			return nil
152		})
153		if err != nil {
154			return store.Subscription{}, err
155		}
156		s.publish(ctx, orgID, "subscription.updated", sub)
157		if !upgrade {
158			return sub, nil
159		}
160		paid, err := s.prorate(ctx, sub, oldPlan, newPlan, oldValue, newValue)
161		if err != nil {
162			return sub, err
163		}
164		if !paid {
165			return s.setStatus(ctx, sub, store.PastDue)
166		}
167		return sub, nil
168	}
169	
170	// prorate bills an upgrade for the time left in the current period: the unused part of the old value is credited and the
171	// remaining part of the new value is charged. The period does not change.
172	func (s *Service) prorate(ctx context.Context, sub store.Subscription, oldPlan, newPlan store.Plan, oldValue, newValue int64) (bool, error) {
173		now := s.Clock.Now()
174		remaining := int64(sub.CurrentPeriodEnd.Sub(now) / time.Second)
175		length := int64(sub.CurrentPeriodEnd.Sub(sub.CurrentPeriodStart) / time.Second)
176		lines := []store.Line{
177			{Description: "Unused time on " + oldPlan.Name, Quantity: 1, UnitAmount: -money.Prorate(oldValue, remaining, length)},
178			{Description: "Remaining time on " + newPlan.Name, Quantity: 1, UnitAmount: money.Prorate(newValue, remaining, length)},
179		}
180		return s.bill(ctx, sub, newPlan.Currency, lines, now, sub.CurrentPeriodEnd)
181	}
182	
183	// Cancel cancels a subscription now, or at the end of its current period when atPeriodEnd is set. Canceling a canceled
184	// subscription changes nothing.
185	func (s *Service) Cancel(ctx context.Context, orgID, id string, atPeriodEnd bool) (store.Subscription, error) {
186		now := s.Clock.Now()
187		sub, err := s.Store.UpdateSubscription(orgID, id, func(sub *store.Subscription) error {
188			if sub.Status == store.Canceled {
189				return nil
190			}
191			if atPeriodEnd {
192				sub.CancelAtPeriodEnd = true
193				return nil
194			}
195			sub.Status, sub.CanceledAt = store.Canceled, &now
196			return nil
197		})
198		if err != nil {
199			return store.Subscription{}, err
200		}
201		if sub.Status == store.Canceled {
202			s.publish(ctx, orgID, "subscription.canceled", sub)
203		} else {
204			s.publish(ctx, orgID, "subscription.updated", sub)
205		}
206		return sub, nil
207	}
208	
209	// RenewDue renews every subscription, of every organization, whose current period has ended. A subscription set to cancel
210	// at the end of its period is canceled. Otherwise its next period starts and is invoiced: a licensed plan bills the new
211	// period in advance, a metered plan bills the usage of the period that ended. A declined charge makes the subscription past
212	// due. RenewDue returns how many subscriptions it renewed or canceled.
213	func (s *Service) RenewDue(ctx context.Context) (int, error) {
214		now := s.Clock.Now()
215		n := 0
216		for _, sub := range s.Store.DueSubscriptions(now) {
217			if err := ctx.Err(); err != nil {
218				return n, err
219			}
220			if err := s.renew(ctx, sub, now); err != nil {
221				return n, fmt.Errorf("renew %s: %w", sub.ID, err)
222			}
223			n++
224		}
225		return n, nil
226	}
227	
228	func (s *Service) renew(ctx context.Context, sub store.Subscription, now time.Time) error {
229		plan, ok := s.Store.Plan(sub.OrgID, sub.PlanID)
230		if !ok {
231			return store.ErrNotFound
232		}
233		if sub.CancelAtPeriodEnd {
234			end := sub.CurrentPeriodEnd
235			sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
236				x.Status, x.CanceledAt = store.Canceled, &end
237				return nil
238			})
239			if err == nil {
240				s.publish(ctx, sub.OrgID, "subscription.canceled", sub)
241			}
242			return err
243		}
244		pending := sub.PendingPlanID != nil || sub.PendingQuantity != nil
245		if sub.PendingPlanID != nil {
246			if plan, ok = s.Store.Plan(sub.OrgID, *sub.PendingPlanID); !ok {
247				return store.ErrNotFound
248			}
249			sub.PlanID = plan.ID
250		}
251		if sub.PendingQuantity != nil {
252			sub.Quantity = *sub.PendingQuantity
253		}
254		start := now
255		end := billing.AddInterval(start, plan.Interval)
256		paid := true
257		var err error
258		switch {
259		case plan.UsageType == store.Metered && sub.Status != store.Trialing:
260			paid, err = s.invoicePeriod(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
261		case plan.UsageType == store.Licensed:
262			paid, err = s.invoicePeriod(ctx, sub, plan, start, end)
263		}
264		if err != nil {
265			return err
266		}
267		sub, err = s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
268			x.CurrentPeriodStart, x.CurrentPeriodEnd = start, end
269			if pending {
270				x.PlanID, x.Quantity = sub.PlanID, sub.Quantity
271				x.PendingPlanID, x.PendingQuantity = nil, nil
272			}
273			if paid {
274				x.Status = store.Active
275			} else {
276				x.Status = store.PastDue
277			}
278			return nil
279		})
280		if err != nil {
281			return err
282		}
283		s.publish(ctx, sub.OrgID, "subscription.updated", sub)
284		return nil
285	}
286	
287	// invoicePeriod invoices one period of a subscription and charges the invoice to the customer's default payment method.
288	// It reports false when the charge was declined. An invoice that needs no charge is marked paid; one whose customer has no
289	// payment method stays open and counts as paid here (it is paid by hand).
290	func (s *Service) invoicePeriod(ctx context.Context, sub store.Subscription, plan store.Plan, start, end time.Time) (bool, error) {
291		var lines []store.Line
292		period := start.Format("Jan 2, 2006") + " to " + end.Format("Jan 2, 2006")
293		switch plan.UsageType {
294		case store.Licensed:
295			if plan.UnitAmount > 0 {
296				lines = append(lines, store.Line{Description: plan.Name + ", " + period, Quantity: int64(sub.Quantity), UnitAmount: plan.UnitAmount})
297			}
298		case store.Metered:
299			if used := s.Store.UsageTotal(sub.OrgID, sub.ID, start, end); used > 0 {
300				lines = append(lines, store.Line{Description: plan.Name + " usage, " + period, Quantity: used, UnitAmount: plan.UnitAmount})
301			}
302		}
303		return s.bill(ctx, sub, plan.Currency, lines, start, end)
304	}
305	
306	// bill invoices lines for the period from start to end and charges the invoice to the customer's default payment method.
307	// It reports false when the charge was declined.
308	func (s *Service) bill(ctx context.Context, sub store.Subscription, currency money.Currency, lines []store.Line, start, end time.Time) (bool, error) {
309		ps, pe := start, end
310		inv, err := s.Store.CreateInvoice(store.Invoice{OrgID: sub.OrgID, CustomerID: sub.CustomerID, SubscriptionID: sub.ID, Currency: currency,
311			Lines: lines, DiscountPercent: sub.DiscountPercent, PeriodStart: &ps, PeriodEnd: &pe}, s.Clock.Now())
312		if err != nil {
313			return false, err
314		}
315		s.publish(ctx, sub.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID, "subscription_id": sub.ID})
316		_, _, err = s.Payments.Pay(ctx, sub.OrgID, inv.ID, "")
317		var decline *payments.DeclineError
318		switch {
319		case err == nil, errors.Is(err, payments.ErrNoPaymentMethod):
320			return true, nil
321		case errors.As(err, &decline):
322			return false, nil
323		default:
324			return false, err
325		}
326	}
327	
328	func (s *Service) setStatus(ctx context.Context, sub store.Subscription, st store.SubStatus) (store.Subscription, error) {
329		sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
330			x.Status = st
331			return nil
332		})
333		if err == nil {
334			s.publish(ctx, sub.OrgID, "subscription.updated", sub)
335		}
336		return sub, err
337	}
338	
339	func (s *Service) publish(ctx context.Context, orgID, typ string, data any) {
340		if s.Publisher != nil {
341			_ = s.Publisher.Publish(ctx, orgID, typ, data)
342		}
343	}
