287	// invoicePeriod invoices one period of a subscription and charges the invoice to the customer's default payment method.
288	// It reports false when the charge was declined. An invoice that needs no charge is marked paid; one whose customer has no
289	// payment method stays open and counts as paid here (it is paid by hand).
290	func (s *Service) invoicePeriod(ctx context.Context, sub store.Subscription, plan store.Plan, start, end time.Time) (bool, error) {
291		var lines []store.Line
292		period := start.Format("Jan 2, 2006") + " to " + end.Format("Jan 2, 2006")
293		switch plan.UsageType {
294		case store.Licensed:
295			if plan.UnitAmount > 0 {
296				lines = append(lines, store.Line{Description: plan.Name + ", " + period, Quantity: int64(sub.Quantity), UnitAmount: plan.UnitAmount})
297			}
298		case store.Metered:
299			if used := s.Store.UsageTotal(sub.OrgID, sub.ID, start, end); used > 0 {
300				lines = append(lines, store.Line{Description: plan.Name + " usage, " + period, Quantity: used, UnitAmount: plan.UnitAmount})
301			}
302		}
303		return s.bill(ctx, sub, plan.Currency, lines, start, end)
304	}
305	
306	// bill invoices lines for the period from start to end and charges the invoice to the customer's default payment method.
307	// It reports false when the charge was declined.
308	func (s *Service) bill(ctx context.Context, sub store.Subscription, currency money.Currency, lines []store.Line, start, end time.Time) (bool, error) {
309		ps, pe := start, end
310		inv, err := s.Store.CreateInvoice(store.Invoice{OrgID: sub.OrgID, CustomerID: sub.CustomerID, SubscriptionID: sub.ID, Currency: currency,
311			Lines: lines, DiscountPercent: sub.DiscountPercent, PeriodStart: &ps, PeriodEnd: &pe}, s.Clock.Now())
312		if err != nil {
313			return false, err
314		}
315		s.publish(ctx, sub.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID, "subscription_id": sub.ID})
316		_, _, err = s.Payments.Pay(ctx, sub.OrgID, inv.ID, "")
317		var decline *payments.DeclineError
318		switch {
319		case err == nil, errors.Is(err, payments.ErrNoPaymentMethod):
320			return true, nil
321		case errors.As(err, &decline):
322			return false, nil
323		default:
324			return false, err
325		}
326	}
327	
328	func (s *Service) setStatus(ctx context.Context, sub store.Subscription, st store.SubStatus) (store.Subscription, error) {
329		sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
330			x.Status = st
331			return nil
332		})
333		if err == nil {
334			s.publish(ctx, sub.OrgID, "subscription.updated", sub)
335		}
336		return sub, err
337	}
338	
339	func (s *Service) publish(ctx context.Context, orgID, typ string, data any) {
340		if s.Publisher != nil {
341			_ = s.Publisher.Publish(ctx, orgID, typ, data)
342		}
343	}
