func TestWebhookEndpoints(t *testing.T) {

data.output:
1	// Package subscriptions runs subscriptions: starting them with their first invoice, changing and canceling them, and
2	// renewing them when a billing period ends.
3	package subscriptions
4	
5	import (
6		"context"
7		"errors"
8		"fmt"
9		"time"
10	
11		"example.com/tally/internal/billing"
12		"example.com/tally/internal/clock"
13		"example.com/tally/internal/money"
14		"example.com/tally/internal/payments"
15		"example.com/tally/internal/store"
16	)
17	
18	// Errors.
19	var (
20		ErrPlanInactive     = errors.New("the plan is not active")
21		ErrCanceled         = errors.New("the subscription is canceled")
22		ErrIncompatiblePlan = errors.New("the plans must have the same currency and interval, and neither may be metered")
23	)
24	
25	// Service runs subscriptions.
26	type Service struct {
27		Store     *store.Store
28		Payments  *payments.Service
29		Clock     clock.Clock
30		Publisher payments.Publisher // nil: no events
31	}
32	
33	// CreateInput is a new subscription.
34	type CreateInput struct {
35		CustomerID      string
36		PlanID          string
37		Quantity        int // 0 means 1
38		DiscountPercent int
39	}
40	
41	// Create starts a subscription now. With a plan that has a trial, the subscription is trialing until the trial ends, and
42	// its first period starts then. Otherwise its first period starts now; for a licensed plan that period is invoiced at once
43	// and charged to the customer's default payment method, if it has one (a declined charge makes the subscription past due).
44	func (s *Service) Create(ctx context.Context, orgID string, in CreateInput) (store.Subscription, error) {
45		plan, ok := s.Store.Plan(orgID, in.PlanID)
46		if !ok {
47			return store.Subscription{}, store.ErrNotFound
48		}
49		if !plan.Active {
50			return store.Subscription{}, ErrPlanInactive
51		}
52		if in.Quantity == 0 {
53			in.Quantity = 1
54		}
55		now := s.Clock.Now()
56		sub := store.Subscription{OrgID: orgID, CustomerID: in.CustomerID, PlanID: plan.ID, Quantity: in.Quantity, DiscountPercent: in.DiscountPercent,
57			StartedAt: now, CurrentPeriodStart: now}
58		if plan.TrialDays > 0 {
59			end := now.AddDate(0, 0, plan.TrialDays)
60			sub.Status, sub.TrialEnd, sub.CurrentPeriodEnd = store.Trialing, &end, end
61		} else {
62			sub.Status, sub.CurrentPeriodEnd = store.Active, billing.AddInterval(now, plan.Interval)
63		}
64		sub, err := s.Store.CreateSubscription(sub, now)
65		if err != nil {
66			return store.Subscription{}, err
67		}
68		s.publish(ctx, orgID, "subscription.created", sub)
69		if sub.Status == store.Active && plan.UsageType == store.Licensed {
70			paid, err := s.invoicePeriod(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
71			if err != nil {
72				return sub, err
73			}
74			if !paid {
75				if sub, err = s.setStatus(ctx, sub, store.PastDue); err != nil {
76					return sub, err
77				}
78			}
79		}
80		return sub, nil
81	}
82	
83	// UpdateInput changes a subscription; nil fields stay as they are.
84	type UpdateInput struct {
85		PlanID   *string
86		Quantity *int
87	}
88	
89	// Update changes a subscription's plan or quantity. A change that raises the subscription's value (its plan's unit amount
90	// times its quantity) is an upgrade: it applies at once and its unused and remaining time are billed at once. A change that
91	// lowers it is a downgrade: it becomes pending and applies at the next renewal. A change that keeps the value equal, and any
92	// change of a trialing subscription, applies at once and bills nothing.
93	func (s *Service) Update(ctx context.Context, orgID, id string, in UpdateInput) (store.Subscription, error) {
94		if in.PlanID != nil {
95			p, ok := s.Store.Plan(orgID, *in.PlanID)
96			if !ok {
97				return store.Subscription{}, store.ErrNotFound
98			}
99			if !p.Active {
100				return store.Subscription{}, ErrPlanInactive
101			}
102		}
103		cur, ok := s.Store.Subscription(orgID, id)
104		if !ok {
105			return store.Subscription{}, store.ErrNotFound
106		}
107		if cur.Status == store.Canceled {
108			return store.Subscription{}, ErrCanceled
109		}
110		oldPlan, ok := s.Store.Plan(orgID, cur.PlanID)
111		if !ok {
112			return store.Subscription{}, store.ErrNotFound
113		}
114		newPlan, quantity := oldPlan, cur.Quantity
115		if in.PlanID != nil {
116			newPlan, _ = s.Store.Plan(orgID, *in.PlanID)
117		}
118		if in.Quantity != nil {
119			quantity = *in.Quantity
120		}
121		if quantity <= 0 {
122			return store.Subscription{}, fmt.Errorf("%w: the quantity must be at least 1", store.ErrInvalid)
123		}
124		changed := newPlan.ID != oldPlan.ID || quantity != cur.Quantity
125		if changed && (oldPlan.UsageType == store.Metered || newPlan.UsageType == store.Metered ||
126			oldPlan.Currency != newPlan.Currency || oldPlan.Interval != newPlan.Interval) {
127			return store.Subscription{}, ErrIncompatiblePlan
128		}
129		oldValue := oldPlan.UnitAmount * int64(cur.Quantity)
130		newValue := newPlan.UnitAmount * int64(quantity)
131		trialing := cur.Status == store.Trialing
132		downgrade := !trialing && newValue < oldValue
133		upgrade := !trialing && newValue > oldValue
134	
135		sub, err := s.Store.UpdateSubscription(orgID, id, func(sub *store.Subscription) error {
136			if sub.Status == store.Canceled {
137				return ErrCanceled
138			}
139			if downgrade {
140				planID := newPlan.ID
141				sub.PendingPlanID, sub.PendingQuantity = &planID, &quantity
142				return nil
143			}
144			if in.PlanID != nil {
145				sub.PlanID = *in.PlanID
146			}
147			if in.Quantity != nil {
148				sub.Quantity = *in.Quantity
149			}
150			sub.PendingPlanID, sub.PendingQuantity = nil, nil
151			return nil
152		})
153		if err != nil {
154			return store.Subscription{}, err
155		}
156		s.publish(ctx, orgID, "subscription.updated", sub)
157		if !upgrade {
158			return sub, nil
159		}
160		paid, err := s.prorate(ctx, sub, oldPlan, newPlan, oldValue, newValue)
161		if err != nil {
162			return sub, err
163		}
164		if !paid {
165			return s.setStatus(ctx, sub, store.PastDue)
166		}
167		return sub, nil
168	}
169	
170	// prorate bills an upgrade for the time left in the current period: the unused part of the old value is credited and the
171	// remaining part of the new value is charged. The period does not change. When the period has already ended but its renewal
172	// has not run yet, nothing is left to prorate: the remaining time is zero, so the upgrade bills nothing and the renewal
173	// bills the new plan in full.
174	func (s *Service) prorate(ctx context.Context, sub store.Subscription, oldPlan, newPlan store.Plan, oldValue, newValue int64) (bool, error) {
175		now, end := s.Clock.Now(), sub.CurrentPeriodEnd
176		if end.Before(now) {
177			end = now
178		}
179		remaining := int64(end.Sub(now) / time.Second)
180		length := int64(sub.CurrentPeriodEnd.Sub(sub.CurrentPeriodStart) / time.Second)
181		lines := []store.Line{
182			{Description: "Unused time on " + oldPlan.Name, Quantity: 1, UnitAmount: -money.Prorate(oldValue, remaining, length)},
183			{Description: "Remaining time on " + newPlan.Name, Quantity: 1, UnitAmount: money.Prorate(newValue, remaining, length)},
184		}
185		return s.bill(ctx, sub, newPlan.Currency, lines, now, end)
186	}
187	
188	// Cancel cancels a subscription now, or at the end of its current period when atPeriodEnd is set. Canceling a canceled
189	// subscription changes nothing.
190	func (s *Service) Cancel(ctx context.Context, orgID, id string, atPeriodEnd bool) (store.Subscription, error) {
191		now := s.Clock.Now()
192		sub, err := s.Store.UpdateSubscription(orgID, id, func(sub *store.Subscription) error {
193			if sub.Status == store.Canceled {
194				return nil
195			}
196			if atPeriodEnd {
197				sub.CancelAtPeriodEnd = true
198				return nil
199			}
200			sub.Status, sub.CanceledAt = store.Canceled, &now
201			return nil
202		})
203		if err != nil {
204			return store.Subscription{}, err
205		}
206		if sub.Status == store.Canceled {
207			s.publish(ctx, orgID, "subscription.canceled", sub)
208		} else {
209			s.publish(ctx, orgID, "subscription.updated", sub)
210		}
211		return sub, nil
212	}
213	
214	// RenewDue renews every subscription, of every organization, whose current period has ended. A subscription set to cancel
215	// at the end of its period is canceled. Otherwise its next period starts and is invoiced: a licensed plan bills the new
216	// period in advance, a metered plan bills the usage of the period that ended. A declined charge makes the subscription past
217	// due. RenewDue returns how many subscriptions it renewed or canceled.
218	func (s *Service) RenewDue(ctx context.Context) (int, error) {
219		now := s.Clock.Now()
220		n := 0
221		for _, sub := range s.Store.DueSubscriptions(now) {
222			if err := ctx.Err(); err != nil {
223				return n, err
224			}
225			if err := s.renew(ctx, sub, now); err != nil {
226				return n, fmt.Errorf("renew %s: %w", sub.ID, err)
227			}
228			n++
229		}
230		return n, nil
231	}
232	
233	func (s *Service) renew(ctx context.Context, sub store.Subscription, now time.Time) error {
234		plan, ok := s.Store.Plan(sub.OrgID, sub.PlanID)
235		if !ok {
236			return store.ErrNotFound
237		}
238		if sub.CancelAtPeriodEnd {
239			end := sub.CurrentPeriodEnd
240			sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
241				x.Status, x.CanceledAt = store.Canceled, &end
242				return nil
243			})
244			if err == nil {
245				s.publish(ctx, sub.OrgID, "subscription.canceled", sub)
246			}
247			return err
248		}
249		pending := sub.PendingPlanID != nil || sub.PendingQuantity != nil
250		if sub.PendingPlanID != nil {
251			if plan, ok = s.Store.Plan(sub.OrgID, *sub.PendingPlanID); !ok {
252				return store.ErrNotFound
253			}
254			sub.PlanID = plan.ID
255		}
256		if sub.PendingQuantity != nil {
257			sub.Quantity = *sub.PendingQuantity
258		}
259		start := now
260		end := billing.AddInterval(start, plan.Interval)
261		paid := true
262		var err error
263		switch {
264		case plan.UsageType == store.Metered && sub.Status != store.Trialing:
265			paid, err = s.invoicePeriod(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
266		case plan.UsageType == store.Licensed:
267			paid, err = s.invoicePeriod(ctx, sub, plan, start, end)
268		}
269		if err != nil {
270			return err
271		}
272		sub, err = s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
273			x.CurrentPeriodStart, x.CurrentPeriodEnd = start, end
274			if pending {
275				x.PlanID, x.Quantity = sub.PlanID, sub.Quantity
276				x.PendingPlanID, x.PendingQuantity = nil, nil
277			}
278			if paid {
279				x.Status = store.Active
280			} else {
281				x.Status = store.PastDue
282			}
283			return nil
284		})
285		if err != nil {
286			return err
287		}
288		s.publish(ctx, sub.OrgID, "subscription.updated", sub)
289		return nil
290	}
291	
292	// invoicePeriod invoices one period of a subscription and charges the invoice to the customer's default payment method.
293	// It reports false when the charge was declined. An invoice that needs no charge is marked paid; one whose customer has no
294	// payment method stays open and counts as paid here (it is paid by hand).
295	func (s *Service) invoicePeriod(ctx context.Context, sub store.Subscription, plan store.Plan, start, end time.Time) (bool, error) {
296		var lines []store.Line
297		period := start.Format("Jan 2, 2006") + " to " + end.Format("Jan 2, 2006")
298		switch plan.UsageType {
299		case store.Licensed:
300			if plan.UnitAmount > 0 {
301				lines = append(lines, store.Line{Description: plan.Name + ", " + period, Quantity: int64(sub.Quantity), UnitAmount: plan.UnitAmount})
302			}
303		case store.Metered:
304			if used := s.Store.UsageTotal(sub.OrgID, sub.ID, start, end); used > 0 {
305				lines = append(lines, store.Line{Description: plan.Name + " usage, " + period, Quantity: used, UnitAmount: plan.UnitAmount})
306			}
307		}
308		return s.bill(ctx, sub, plan.Currency, lines, start, end)
309	}
310	
311	// bill invoices lines for the period from start to end and charges the invoice to the customer's default payment method.
312	// It reports false when the charge was declined.
313	func (s *Service) bill(ctx context.Context, sub store.Subscription, currency money.Currency, lines []store.Line, start, end time.Time) (bool, error) {
314		ps, pe := start, end
315		inv, err := s.Store.CreateInvoice(store.Invoice{OrgID: sub.OrgID, CustomerID: sub.CustomerID, SubscriptionID: sub.ID, Currency: currency,
316			Lines: lines, DiscountPercent: sub.DiscountPercent, PeriodStart: &ps, PeriodEnd: &pe}, s.Clock.Now())
317		if err != nil {
318			return false, err
319		}
320		s.publish(ctx, sub.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID, "subscription_id": sub.ID})
321		_, _, err = s.Payments.Pay(ctx, sub.OrgID, inv.ID, "")
322		var decline *payments.DeclineError
323		switch {
324		case err == nil, errors.Is(err, payments.ErrNoPaymentMethod):
325			return true, nil
326		case errors.As(err, &decline):
327			return false, nil
328		default:
329			return false, err
330		}
331	}
332	
333	func (s *Service) setStatus(ctx context.Context, sub store.Subscription, st store.SubStatus) (store.Subscription, error) {
334		sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
335			x.Status = st
336			return nil
337		})
338		if err == nil {
339			s.publish(ctx, sub.OrgID, "subscription.updated", sub)
340		}
341		return sub, err
342	}
343	
344	func (s *Service) publish(ctx context.Context, orgID, typ string, data any) {
345		if s.Publisher != nil {
346			_ = s.Publisher.Publish(ctx, orgID, typ, data)
347		}
348	}
