188	// Cancel cancels a subscription now, or at the end of its current period when atPeriodEnd is set. Canceling a canceled
189	// subscription changes nothing.
190	func (s *Service) Cancel(ctx context.Context, orgID, id string, atPeriodEnd bool) (store.Subscription, error) {
191		now := s.Clock.Now()
192		sub, err := s.Store.UpdateSubscription(orgID, id, func(sub *store.Subscription) error {
193			if sub.Status == store.Canceled {
194				return nil
195			}
196			if atPeriodEnd {
197				sub.CancelAtPeriodEnd = true
198				return nil
199			}
200			sub.Status, sub.CanceledAt = store.Canceled, &now
201			return nil
202		})
203		if err != nil {
204			return store.Subscription{}, err
205		}
206		if sub.Status == store.Canceled {
207			s.publish(ctx, orgID, "subscription.canceled", sub)
208		} else {
209			s.publish(ctx, orgID, "subscription.updated", sub)
210		}
211		return sub, nil
212	}
