214	// RenewDue renews every subscription, of every organization, whose current period has ended. A subscription set to cancel
215	// at the end of its period is canceled. Otherwise its next period starts and is invoiced: a licensed plan bills the new
216	// period in advance, a metered plan bills the usage of the period that ended. A declined charge makes the subscription past
217	// due. RenewDue returns how many subscriptions it renewed or canceled.
218	func (s *Service) RenewDue(ctx context.Context) (int, error) {
219		now := s.Clock.Now()
220		n := 0
221		for _, sub := range s.Store.DueSubscriptions(now) {
222			if err := ctx.Err(); err != nil {
223				return n, err
224			}
225			if err := s.renew(ctx, sub, now); err != nil {
226				return n, fmt.Errorf("renew %s: %w", sub.ID, err)
227			}
228			n++
229		}
230		return n, nil
231	}
