292	// invoicePeriod invoices one period of a subscription and charges the invoice to the customer's default payment method.
293	// It reports false when the charge was declined. An invoice that needs no charge is marked paid; one whose customer has no
294	// payment method stays open and counts as paid here (it is paid by hand).
295	func (s *Service) invoicePeriod(ctx context.Context, sub store.Subscription, plan store.Plan, start, end time.Time) (bool, error) {
296		var lines []store.Line
297		period := start.Format("Jan 2, 2006") + " to " + end.Format("Jan 2, 2006")
298		switch plan.UsageType {
299		case store.Licensed:
300			if plan.UnitAmount > 0 {
301				lines = append(lines, store.Line{Description: plan.Name + ", " + period, Quantity: int64(sub.Quantity), UnitAmount: plan.UnitAmount})
302			}
303		case store.Metered:
304			if used := s.Store.UsageTotal(sub.OrgID, sub.ID, start, end); used > 0 {
305				lines = append(lines, store.Line{Description: plan.Name + " usage, " + period, Quantity: used, UnitAmount: plan.UnitAmount})
306			}
307		}
308		return s.bill(ctx, sub, plan.Currency, lines, start, end)
309	}
