311	// bill invoices lines for the period from start to end and charges the invoice to the customer's default payment method.
312	// It reports false when the charge was declined.
313	func (s *Service) bill(ctx context.Context, sub store.Subscription, currency money.Currency, lines []store.Line, start, end time.Time) (bool, error) {
314		ps, pe := start, end
315		inv, err := s.Store.CreateInvoice(store.Invoice{OrgID: sub.OrgID, CustomerID: sub.CustomerID, SubscriptionID: sub.ID, Currency: currency,
316			Lines: lines, DiscountPercent: sub.DiscountPercent, PeriodStart: &ps, PeriodEnd: &pe}, s.Clock.Now())
317		if err != nil {
318			return false, err
319		}
320		s.publish(ctx, sub.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID, "subscription_id": sub.ID})
321		_, _, err = s.Payments.Pay(ctx, sub.OrgID, inv.ID, "")
322		var decline *payments.DeclineError
323		switch {
324		case err == nil, errors.Is(err, payments.ErrNoPaymentMethod):
325			return true, nil
326		case errors.As(err, &decline):
327			return false, nil
328		default:
329			return false, err
330		}
331	}
