	_, _ = e.Store.UpdateCustomer(e.Acme.ID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_card_visa"; return nil })
	team := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	business := e.CreatePlan(e.Acme, "Business", "USD", "50.00")
	pro := e.CreatePlan(e.Acme, "Pro", "USD", "25.00")
	var sub store.Subscription
	e.MustDo(http.StatusCreated, "POST", "/v1/subscriptions", e.Acme.Key, map[string]any{"customer_id": c.ID, "plan_id": team.ID}, &sub)
	// 21 of the period's 31 days remain: the unused 2000 is credited and the remaining 5000 is charged.
	e.Clock.Set(sub.CurrentPeriodStart.AddDate(0, 0, 10))

	var got store.Subscription
	e.MustDo(http.StatusOK, "PATCH", "/v1/subscriptions/"+sub.ID, e.Acme.Key, map[string]any{"plan_id": business.ID}, &got)
	if got.PlanID != business.ID || got.Status != store.Active {
		t.Fatalf("upgrade = %+v", got)
	}
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	if len(invs) != 2 || len(invs[1].Lines) != 2 ||
		invs[1].Lines[0] != (store.Line{Description: "Unused time on Team", Quantity: 1, UnitAmount: -1355}) ||
		invs[1].Lines[1] != (store.Line{Description: "Remaining time on Business", Quantity: 1, UnitAmount: 3387}) {
		t.Fatalf("upgrade invoice = %+v", invs)
	}
	if cs := e.Gateway.Charges(); len(cs) != 2 || cs[1].Amount != 2032 {
		t.Fatalf("charges = %+v", cs)
	}

	// Pro at 25.00 x 2 is worth the same as Business at 50.00 x 1: the change applies at once and bills nothing.
	e.MustDo(http.StatusOK, "PATCH", "/v1/subscriptions/"+sub.ID, e.Acme.Key, map[string]any{"plan_id": pro.ID, "quantity": 2}, &got)
	if got.PlanID != pro.ID || got.Quantity != 2 || got.PendingPlanID != nil {
		t.Fatalf("equal change = %+v", got)
	}
	if n := len(e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})); n != 2 {
		t.Fatalf("an equal change was billed: %d invoices", n)
	}

	// A trialing subscription applies any change at once and bills nothing.
	var trial store.Plan
	r := e.Do("POST", "/v1/plans", e.Acme.Key, map[string]any{"name": "Trial", "currency": "USD", "price": "30.00", "interval": "month", "trial_days": 14})
	if r.Code != http.StatusCreated {
		t.Fatalf("create trial plan: %s", r)
	}
	r.JSON(t, &trial)
	c2 := e.CreateCustomer(e.Acme, "Joe", "joe@example.com")
	var tsub store.Subscription
	e.MustDo(http.StatusCreated, "POST", "/v1/subscriptions", e.Acme.Key, map[string]any{"customer_id": c2.ID, "plan_id": trial.ID}, &tsub)
	if tsub.Status != store.Trialing {
		t.Fatalf("subscription = %+v", tsub)
	}
	e.MustDo(http.StatusOK, "PATCH", "/v1/subscriptions/"+tsub.ID, e.Acme.Key, map[string]any{"plan_id": business.ID}, &got)
	if got.PlanID != business.ID || got.Status != store.Trialing || got.PendingPlanID != nil {
		t.Fatalf("trial change = %+v", got)
	}
	if n := len(e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: tsub.ID})); n != 0 {
		t.Fatalf("a trial change was billed: %d invoices", n)
	}
}

func TestPendingDowngradeAppliesAtRenewalOverTheAPI(t *testing.T) {

package subscriptions_test

import (
	"context"
	"errors"
	"testing"
	"time"

	"example.com/tally/internal/apitest"
	"example.com/tally/internal/money"
	"example.com/tally/internal/store"
	"example.com/tally/internal/subscriptions"
)

func plan(t *testing.T, e *apitest.Env, name string, unit int64) store.Plan {
	t.Helper()
	p, err := e.Store.CreatePlan(store.Plan{OrgID: e.Acme.ID, Name: name, Currency: money.USD, UnitAmount: unit, Interval: store.Monthly}, e.Clock.Now())
	if err != nil {
		t.Fatal(err)
	}
	return p
}

// subscribe starts a subscription to p for a new customer whose default payment method is pm (empty for none).
func subscribe(t *testing.T, e *apitest.Env, p store.Plan, pm string, qty, discount int) store.Subscription {
	t.Helper()
	c := e.CreateCustomer(e.Acme, "Jane", "jane+"+p.ID+"@example.com")
	if pm != "" {
		_, _ = e.Store.UpdateCustomer(e.Acme.ID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = pm; return nil })
	}
	sub, err := e.Subs.Create(context.Background(), e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: qty, DiscountPercent: discount})
	if err != nil {
		t.Fatal(err)
	}
	return sub
}

func invoicesOf(e *apitest.Env, sub store.Subscription) []store.Invoice {
	return e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
}

func TestUpgradeBillsTheTimeLeftInThePeriod(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	team, business := plan(t, e, "Team", 2000), plan(t, e, "Business", 5000)
	sub := subscribe(t, e, team, "pm_card_visa", 1, 10)
	// 10 of the period's 31 days have passed: 21 days (1814400 s) of 2678400 s remain.
	e.Clock.Set(sub.CurrentPeriodStart.AddDate(0, 0, 10))
	id := business.ID
	got, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &id})
	if err != nil {
		t.Fatal(err)
	}
	if got.PlanID != business.ID || got.Status != store.Active || !got.CurrentPeriodStart.Equal(sub.CurrentPeriodStart) || !got.CurrentPeriodEnd.Equal(sub.CurrentPeriodEnd) {
		t.Fatalf("subscription = %+v", got)
	}
	invs := invoicesOf(e, sub)
	if len(invs) != 2 {
		t.Fatalf("invoices = %+v", invs)
	}
	up := invs[1]
	// Unused: -round(2000 * 21/31) = -1355. Remaining: round(5000 * 21/31) = 3387. The 10% discount is 203 of 2032.
	want := []store.Line{{Description: "Unused time on Team", Quantity: 1, UnitAmount: -1355}, {Description: "Remaining time on Business", Quantity: 1, UnitAmount: 3387}}
	if len(up.Lines) != 2 || up.Lines[0] != want[0] || up.Lines[1] != want[1] || up.DiscountPercent != 10 || up.Status != store.InvoicePaid {
		t.Fatalf("upgrade invoice = %+v", up)
	}
	if cs := e.Gateway.Charges(); len(cs) != 2 || cs[1].Amount != 1829 {
		t.Fatalf("charges = %+v", cs)
	}
}

func TestUpgradeAfterThePeriodEndBillsNothingUntilRenewal(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	team, business := plan(t, e, "Team", 2000), plan(t, e, "Business", 5000)
	sub := subscribe(t, e, team, "pm_card_visa", 1, 0)
	// The period has ended but RenewDue has not run: no time remains, so the remaining time is zero, not negative.
	e.Clock.Set(sub.CurrentPeriodEnd.AddDate(0, 0, 1))
	id := business.ID
	got, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &id})
	if err != nil {
		t.Fatal(err)
	}
	if got.PlanID != business.ID || got.Status != store.Active {
		t.Fatalf("subscription = %+v", got)
	}
	invs := invoicesOf(e, sub)
	if len(invs) != 2 || len(invs[1].Lines) != 2 || invs[1].Lines[0].UnitAmount != 0 || invs[1].Lines[1].UnitAmount != 0 || invs[1].Status != store.InvoicePaid {
		t.Fatalf("upgrade invoice = %+v", invs)
	}
	if cs := e.Gateway.Charges(); len(cs) != 1 {
		t.Fatalf("charges = %+v", cs)
	}
	if n, err := e.Subs.RenewDue(ctx); err != nil || n != 1 {
		t.Fatalf("RenewDue = %d, %v", n, err)
	}
	invs = invoicesOf(e, sub)
	if len(invs) != 3 || len(invs[2].Lines) != 1 || invs[2].Lines[0].Quantity != 1 || invs[2].Lines[0].UnitAmount != 5000 {
		t.Fatalf("renewal invoice = %+v", invs)
	}
	if cs := e.Gateway.Charges(); len(cs) != 2 || cs[1].Amount != 5000 {
		t.Fatalf("charges = %+v", cs)
	}
}

