	s.log.Error("upgrade invoice", "subscription", sub.ID, "err", err)
	writeJSON(w, http.StatusBadGateway, map[string]any{"error": "upgrade_not_billed",
		"message": "the plan change was applied but its charge could not be made; the subscription is past_due", "subscription": sub})
	return
}
writeJSON(w, http.StatusOK, sub)

