279			x.CurrentPeriodStart, x.CurrentPeriodEnd = start, end
280			if pending {
281				x.PlanID, x.Quantity = sub.PlanID, sub.Quantity
282				x.PendingPlanID, x.PendingQuantity = nil, nil
283			}
284			if paid {
285				x.Status = store.Active
286			} else {
287				x.Status = store.PastDue
288			}
