298	// invoicePeriod invoices one period of a subscription and charges the invoice to the customer's default payment method.
299	// It reports false when the charge was declined. An invoice that needs no charge is marked paid; one whose customer has no
300	// payment method stays open and counts as paid here (it is paid by hand).
301	func (s *Service) invoicePeriod(ctx context.Context, sub store.Subscription, plan store.Plan, start, end time.Time) (bool, error) {
302		var lines []store.Line
303		period := start.Format("Jan 2, 2006") + " to " + end.Format("Jan 2, 2006")
304		switch plan.UsageType {
305		case store.Licensed:
306			if plan.UnitAmount > 0 {
307				lines = append(lines, store.Line{Description: plan.Name + ", " + period, Quantity: int64(sub.Quantity), UnitAmount: plan.UnitAmount})
308			}
309		case store.Metered:
310			if used := s.Store.UsageTotal(sub.OrgID, sub.ID, start, end); used > 0 {
311				lines = append(lines, store.Line{Description: plan.Name + " usage, " + period, Quantity: used, UnitAmount: plan.UnitAmount})
312			}
313		}
314		return s.bill(ctx, sub, plan.Currency, lines, start, end)
315	}
